The 99 Names of Allah
- #0 Best of Names 7:180; 20:8; 59:24
- #1 الرحمن     الرَّحْمَنُ (ذو الرحمة الواسعة التي تعم جميع الخلق)  1:3; 17:110
- #2 الرحيم     الرَّحِيمُ (المختص برحمته للمؤمنين)  2:163; 3:31; 4:100; 5:3
- #3 الملك     الْمَلِكُ (المالك المتصرف في ملكه كيف يشاء)  20:114; 23:116; 59:23
- #4 القدوس     الْقُدُّوسُ (المنزه عن كل نقص، الطاهر عن كل عيب)  59:23; 62:1
- #5 السلام     السَّلَامُ (السلام من كل نقص وآفة، السالم المقدس)  59:23
- #6 المؤمن     الْمُؤْمِنُ (المصدق لنفسه ورسله وكتبه)  59:23
- #7 المهيمن     الْمُهَيْمِنُ (الشاهد على كل شيء، الرقيب عليه)  59:23
- #8 العزيز     الْعَزِيزُ (الذي لا نظير له، الغالب الذي لا يُغلب)  3:6; 4:158; 9:40; 48:7
- #9 الجبار     الْجَبَّارُ (الذي ينفذ مشيئته بالقهر، ويجبر الكسير)  59:23
- #10 المتكبر     الْمُتَكَبِّرُ (المتصف بصفات العظمة والكبرياء)  59:23
- #11 الخالق     الْخَالِقُ (المبدع للأشياء من العدم على تقدير)  6:102; 13:16; 39:62; 40:62; 59:24
- #12 البارئ     الْبَارِئُ (الذي خلق الخلق بقدرته)  59:24
- #13 المصور     الْمُصَوِّرُ (الذي صور المخلوقات وأعطاها أشكالها)  59:24
- #14 الغفار     الْغَفَّارُ (الستار لذنوب عباده، المتجاوز عن سيئاتهم)  20:82; 38:66; 39:5; 40:42; 71:10
- #15 القهار     الْقَهَّارُ (الذي قهر جميع خلقه وأذلهم لعظمته)  13:16; 14:48; 38:65; 39:4; 40:16
- #16 الوهاب     الْوَهَّابُ (الذي يهب العطايا والمنح لجود وكرم)  3:8; 38:9; 38:35
- #17 الرزاق     الرَّزَّاقُ (الذي خلق الأرزاق وأوصلها إلى خلقه)  51:58
- #18 الفتاح     الْفَتَّاحُ (الذي يفتح خزائن رحمته لعباده)  34:26
- #19 العليم     الْعَلِيمُ (المحيط بكل شيء علماً، يعلم السر والعلن)  2:158; 3:92; 4:35; 24:41; 33:40
- #20 القابض     الْقَابِضُ (الذي يقبض أرزاق من يشاء ويضيقها)  2:245
- #21 الباسط     الْبَاسِطُ (الذي يبسط الرزق لمن يشاء ويوسعه)  2:245
- #22 الخافض     الْخَافِضُ (الذي يخفض الكافرين والمذنبين)  95:5
- #23 الرافع     الرَّافِعُ (الذي يرفع أولياءه بالطاعات)  58:11; 6:83
- #24 المعز     الْمُعِزُّ (الذي يعز من يشاء من عباده)  3:26
- #25 المذل     الْمُذِلُّ (الذي يذل من يشاء من خلقه)  3:26
- #26 السميع     السَّمِيعُ (الذي لا تخفى عليه الأصوات)  2:127; 2:256; 8:17; 49:1
- #27 البصير     الْبَصِيرُ (الذي يبصر كل شيء ولا تخفى عليه خافية)  4:58; 17:1; 42:11; 42:27
- #28 الحكم     الْحَكَمُ (الذي يرجع إليه في قضاء الأمور وفصلها)  22:69
- #29 العدل     الْعَدْلُ (الذي ليس في ملكه عيب ولا نقص)  6:115
- #30 اللطيف     اللَّطِيفُ (الرفيق بعباده، المحسن إليهم)  6:103; 22:63; 31:16; 33:34
- #31 الخبير     الْخَبِيرُ (العالم ببواطن الأمور وخفيّاتها)  6:18; 17:30; 49:13; 59:18
- #32 الحليم     الْحَلِيمُ (الذي لا يعجل بالعقوبة)  2:235; 17:44; 22:59; 35:41
- #33 العظيم     الْعَظِيمُ (الذي لا تدركه العقول ولا تبلغه الأوهام)  2:255; 42:4; 56:96
- #34 الغفور     الْغَفُورُ (الذي يغفر الذنوب ويستر العيوب)  2:173; 8:69; 16:110; 41:32
- #35 الشكور     الشَّكُورُ (الذي يثيب عباده على القليل بالكثير)  35:30; 35:34; 42:23; 64:17
- #36 العلي     الْعَلِيُّ (الرفيع الدرجات، العالي فوق كل شيء)  4:34; 31:30; 42:4; 42:51
- #37 الكبير     الْكَبِيرُ (الذي لا يشبهه شيء، العظيم الجليل)  13:9; 22:62; 31:30
- #38 الحفيظ     الْحَفِيظُ (الحافظ لخلقه، الحارس لكل شيء)  11:57; 34:21; 42:6
- #39 المقيت     الْمُقِيتُ (الذي يخلق أقوات العباد ويقسمها)  4:85
- #40 الحسيب     الْحَسِيبُ (الكافي لعباده، الذي يحاسبهم يوم القيامة)  4:6; 4:86; 33:39
- #41 الجليل     الْجَلِيلُ (العظيم القدر، الرفيع الشأن)  55:27; 39:14; 7:143
- #42 الكريم     الْكَرِيمُ (الذي لا ينقطع عطاؤه وجوده)  27:40; 82:6
- #43 الرقيب     الرَّقِيبُ (المراقب لأحوال العباد، العالم بهم)  4:1; 5:117
- #44 المجيب     الْمُجِيبُ (القابل لدعاء الداعين)  11:61
- #45 الواسع     الْوَاسِعُ (الذي وسعت رحمته كل شيء)  2:268; 3:73; 5:54
- #46 الحكيم     الْحَكِيمُ (المحكم لأموره، العليم الحكيم في أفعاله)  31:27; 46:2; 57:1; 66:2
- #47 الودود     الْوَدُودُ (المحبوب لدى خلقه، المود لهم بالرحمة)  11:90; 85:14
- #48 المجيد     الْمَجِيدُ (الواسع الفضل، العظيم الكرم)  11:73
- #49 الباعث     الْبَاعِثُ (الذي يبعث الموتى للحساب)  22:7
- #50 الشهيد     الشَّهِيدُ (المطلع على كل شيء، الشاهد على عباده)  4:166; 22:17; 41:53; 48:28
- #51 الحق     الْحَقُّ (الثابت الذي لا يزول، الحق في ذاته وأفعاله)  6:62; 22:6; 23:116; 24:25
- #52 الوكيل     الْوَكِيلُ (الكفيل بأمور العباد، الحافظ لهم)  3:173; 4:171; 28:28; 73:9
- #53 القوي     الْقَوِيُّ (الذي لا يعجزه شيء، كامل القوة)  22:40; 22:74; 42:19; 57:25
